'use strict';
function graphRanks(ids,edges){let index=0,stack=[],on=new Set(),idx=new Map(),low=new Map(),components=[],owner=new Map(),adj=new Map(ids.map(id=>[id,[]]));for(let [a,b] of edges)if(a!==b&&adj.has(a)&&adj.has(b))adj.get(a).push(b);function visit(v){idx.set(v,index);low.set(v,index++);stack.push(v);on.add(v);for(let w of adj.get(v)){if(!idx.has(w)){visit(w);low.set(v,Math.min(low.get(v),low.get(w)))}else if(on.has(w))low.set(v,Math.min(low.get(v),idx.get(w)))}if(low.get(v)===idx.get(v)){let c=[],w;do{w=stack.pop();on.delete(w);owner.set(w,components.length);c.push(w)}while(w!==v);components.push(c)}}for(let v of ids)if(!idx.has(v))visit(v);let ranks=components.map(()=>0);for(let i=0;i<components.length;i++)for(let [a,b] of edges){let x=owner.get(a),y=owner.get(b);if(x!==undefined&&y!==undefined&&x!==y)ranks[y]=Math.max(ranks[y],ranks[x]+1)}return new Map(ids.map(id=>[id,ranks[owner.get(id)]]))}
function arrangeUnits(units,edges){let ranks=graphRanks(units.map(u=>u.id),edges),cols=new Map();for(let u of units){let rank=ranks.get(u.id);if(!cols.has(rank))cols.set(rank,[]);cols.get(rank).push(u)}let x=0,height=0;for(let rank of [...cols.keys()].sort((a,b)=>a-b)){let col=cols.get(rank).sort((a,b)=>a.order-b.order||a.id.localeCompare(b.id)),y=0;for(let u of col){u.x=x;u.y=y;y+=u.h+60}height=Math.max(height,y?y-60:0);x+=Math.max(...col.map(u=>u.w))+110}return{w:Math.max(215,x-110),h:Math.max(100,height)}}
function autoArrangeProject(project,heights={}){let next=JSON.parse(JSON.stringify(project)),units=[],members=new Map(),groupIds=new Set(next.groups.map(g=>g.id)),key=n=>n.group&&groupIds.has(n.group)?'g:'+n.group:'n:'+n.id;for(let n of next.nodes){let k=key(n);if(!members.has(k))members.set(k,[]);members.get(k).push(n)}for(let [id,ns] of members){let group=id.startsWith('g:')?next.groups.find(g=>g.id===id.slice(2)):null,local=ns.map(n=>({id:n.id,w:215,h:heights[n.id]||400,order:n.y})),bounds=arrangeUnits(local,next.edges.filter(e=>ns.some(n=>n.id===e.from)&&ns.some(n=>n.id===e.to)).map(e=>[e.from,e.to]));units.push({id,w:bounds.w+(group?56:0),h:bounds.h+(group?110:0),order:Math.min(...ns.map(n=>n.y)),local,group})}let bounds=arrangeUnits(units,next.edges.map(e=>[key(next.nodes.find(n=>n.id===e.from)),key(next.nodes.find(n=>n.id===e.to))]));for(let u of units){if(u.group)Object.assign(u.group,{x:u.x+40,y:u.y+40,w:u.w,h:u.h});for(let loc of u.local){let n=next.nodes.find(n=>n.id===loc.id);n.x=u.x+40+loc.x+(u.group?28:0);n.y=u.y+40+loc.y+(u.group?82:0)}}for(let g of next.groups.filter(g=>!next.nodes.some(n=>n.group===g.id))){g.x=40;g.y=bounds.h+160;bounds.h+=g.h+60}next.canvas={width:Math.max(4800,bounds.w+100),height:Math.max(3200,bounds.h+120)};if(next.canvas.width>20000||next.canvas.height>20000)throw Error('構成が大きすぎるため整理できません');delete next.camera;return next}
